import BookCard from './BookCard';

function BookGrid({ books, status, error, onRetry }) {
  if (status === 'loading') {
    return (
      <div className="grid grid-cols-2 gap-4 md:grid-cols-4 lg:grid-cols-5">
        {Array.from({ length: 10 }).map((_, i) => (
          <div key={i} className="animate-pulse overflow-hidden rounded-xl border border-amber-100 bg-white">
            <div className="aspect-[2/3] bg-slate-100" />
            <div className="p-3 space-y-2">
              <div className="h-3 w-4/5 rounded bg-slate-100" />
              <div className="h-3 w-3/5 rounded bg-slate-100" />
            </div>
          </div>
        ))}
      </div>
    );
  }

  if (status === 'error') {
    return (
      <div className="rounded-xl border border-red-200 bg-red-50 p-8 text-center">
        <p className="font-medium text-red-700">โหลดข้อมูลไม่สำเร็จ</p>
        <p className="mt-1 text-sm text-red-500">{error?.message}</p>
        {onRetry && (
          <button onClick={onRetry}
                  className="mt-4 rounded-lg border border-red-300 bg-white px-4 py-2 text-sm text-red-700 hover:bg-red-50">
            ลองใหม่
          </button>
        )}
      </div>
    );
  }

  if (books.length === 0) {
    return (
      <div className="py-16 text-center">
        <p className="text-4xl">📚</p>
        <p className="mt-3 text-slate-500">ไม่พบหนังสือที่ค้นหา</p>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-2 gap-4 md:grid-cols-4 lg:grid-cols-5">
      {books.map(b => <BookCard key={b.id} book={b} />)}
    </div>
  );
}

export default BookGrid;
